<?php namespace App\Exports; use Maatwebsite\Excel\Concerns\FromCollection; use Maatwebsite\Excel\Concerns\WithHeadings; use Maatwebsite\Excel\Concerns\WithTitle; use Maatwebsite\Excel\Concerns\WithMapping; class GenericExportSheet implements FromCollection, WithHeadings, WithTitle, WithMapping { protected $collectionCallback; protected $sheetTitle; protected $headingsList; protected $mapCallback; public function __construct($sheetTitle, $headingsList, $collectionCallback, $mapCallback = null) { $this->sheetTitle = $sheetTitle; $this->headingsList = $headingsList; $this->collectionCallback = $collectionCallback; $this->mapCallback = $mapCallback; } public function collection() { return call_user_func($this->collectionCallback); } public function headings(): array { return $this->headingsList; } public function map($row): array { if ($this->mapCallback) { return call_user_func($this->mapCallback, $row); } return is_array($row) ? array_values($row) : array_values($row->toArray()); } public function title(): string { return $this->sheetTitle; } }
